={{ (() => {
    const isPage = $('Set Page Number').isExecuted;
    const isChangeVoice = $('Set Change-Voice Page Number').isExecuted;
    const isSample = $('Set Sample Voice Number').isExecuted;
    const isKnit = !isPage && !isChangeVoice && !isSample;
    const left = isKnit ? $('Page Knitting Configuration').item.json['⬅️ Left Page Number'] : null;
    const right = isKnit ? $('Page Knitting Configuration').item.json['Right Page Number ➡️'] : null;
    const p = isKnit
      ? `${left}-${right}_knit`
      : (isPage
          ? $('Set Page Number').item.json.pageNumber
          : (isChangeVoice
              ? $('Set Change-Voice Page Number').item.json.pageNumber
              : 'sample_' + $('Set Sample Voice Number').item.json.voiceId
            )
        );
    const img = isKnit ? `temp/${left}-${right}_knit_image.png` : `temp/${p}_image.png`;
    const cellFile = `temp/${p}_cell.png`;
    const name = isSample ? $('Set Sample Voice Number').item.json.friendlyName : null;

    const sampleImageCmds = isSample ? [
      'REFW=1920',
      'REFH=1080',
      'FONTSIZE=$((REFH / 12))',
      `NAME='${name}'`,
      'NAMELEN=${#NAME}',
      'CELLW=$(( (NAMELEN * FONTSIZE * 6 / 10) + FONTSIZE ))',
      'CELLH=$(( FONTSIZE * 2 ))',
      'COLS=$(( (REFW + CELLW - 1) / CELLW ))',
      'ROWS=$(( (REFH + CELLH - 1) / CELLH ))',
      `ffmpeg -y -f lavfi -i color=white:s=\${CELLW}x\${CELLH} -vf "drawtext=text='\${NAME}':fontcolor=black:fontsize=\${FONTSIZE}:x=(w-text_w)/2:y=(h-text_h)/2" -frames:v 1 ${cellFile}`,
      `ffmpeg -y -i ${cellFile} -filter_complex "tile=\${COLS}x\${ROWS}" -vf "crop=\${REFW}:\${REFH}:0:0" -frames:v 1 ${img}`
    ] : [];

    const ffmpegCmd = isKnit
      ? `ffmpeg -y -loop 1 -t "$DUR" -i ${img} -i temp/${p}_audio.wav -vf "scale=trunc(iw/2)*2:trunc(ih/2)*2" -c:v libx264 -tune stillimage -c:a aac -b:a 192k -pix_fmt yuv420p temp/${p}_clip.mp4`
      : `ffmpeg -y -loop 1 -t "$DUR" -i ${img} -i temp/${p}_audio.wav -filter_complex "[0:v]split[bg_src][fg_src];[bg_src]scale=iw*2:ih,boxblur=20:3[bg];[fg_src]scale=trunc(iw/2)*2:trunc(ih/2)*2[fg];[bg][fg]overlay=(main_w-overlay_w)/2:0[v]" -map "[v]" -map 1:a -c:v libx264 -tune stillimage -c:a aac -b:a 192k -pix_fmt yuv420p temp/${p}_clip.mp4`;

    return [
      'export PATH=/opt/homebrew/bin:/usr/local/bin:$PATH',
      ...sampleImageCmds,
      `DUR=$(ffprobe -v quiet -show_entries format=duration -of csv=p=0 temp/${p}_audio.wav)`,
      `sed -i '' 's/"audioDuration":null/"audioDuration":'"$DUR"'/' temp/${p}_timestamps.json`,
      ffmpegCmd,
      `xattr -d com.apple.quarantine temp/${p}_clip.mp4`
    ].join(' && ');
  })() }}

