={{ (() => {
    const basename = $('Determine Output Basename').item.json.outputBasename;
    const clipGlob = $('Determine Output Basename').item.json.tempClipGlob;
    const chaptersFile = $('Determine Output Basename').item.json.chaptersFile;
    const simple = $('Determine Output Basename').item.json.useSimpleConcat;

    const simpleCmds = [
      'mkdir -p output',
      `find temp -maxdepth 1 -name "${clipGlob}" | sort -V | while read f; do echo "file '$PWD/$f'"; done > temp/${basename}_concat_list.txt`,
      `ffmpeg -y -f concat -safe 0 -i temp/${basename}_concat_list.txt -i temp/${chaptersFile} -map_metadata 1 -c copy output/${basename}.mp4`,
      `xattr -d com.apple.quarantine "$PWD/output/${basename}.mp4" 2>/dev/null; true`
    ];

    const complexCmds = [
      'mkdir -p output',
      `find temp -maxdepth 1 -name "${clipGlob}" | sort -V | while read f; do b=$(basename "$f" _clip.mp4); case "$b" in *_knit) echo "file '$PWD/$f'";; *) ls "temp/\${b}-"*"_knit_clip.mp4" 2>/dev/null | grep -q . || ls "temp/"*"-\${b}_knit_clip.mp4" 2>/dev/null | grep -q . || echo "file '$PWD/$f'";; esac; done > temp/${basename}_concat_list.txt`,
      'MAX_W=0',
      'for f in temp/*_knit_clip.mp4; do [ -f "$f" ] || break; W=$(ffprobe -v quiet -show_entries stream=width -of csv=p=0 "$f" | head -1); if [ "$W" -gt "$MAX_W" ]; then MAX_W=$W; fi; done',
      `SINGLE=$(find temp -maxdepth 1 -name "${clipGlob}" ! -name "*_knit_clip.mp4" | sort -V | head -1)`,
      'if [ -n "$SINGLE" ]; then CLIP_W=$(ffprobe -v quiet -show_entries stream=width -of csv=p=0 "$SINGLE" | head -1); PAGE_W=$((CLIP_W/2)); if [ "$PAGE_W" -gt "$MAX_W" ]; then MAX_W=$PAGE_W; fi; else CLIP_W=$MAX_W; fi',
      'TARGET_W=$MAX_W',
      `if [ "$CLIP_W" -eq "$TARGET_W" ]; then ffmpeg -y -f concat -safe 0 -i temp/${basename}_concat_list.txt -i temp/${chaptersFile} -map_metadata 1 -c copy output/${basename}.mp4; elif [ "$CLIP_W" -gt "$TARGET_W" ]; then X=$(( (CLIP_W - TARGET_W) / 2 )) && ffmpeg -y -f concat -safe 0 -i temp/${basename}_concat_list.txt -i temp/${chaptersFile} -map_metadata 1 -vf "crop=\${TARGET_W}:ih:\${X}:0" -c:v libx264 -preset ultrafast -c:a copy -pix_fmt yuv420p output/${basename}.mp4; else OX=$(( (TARGET_W - CLIP_W) / 2 )) && ffmpeg -y -f concat -safe 0 -i temp/${basename}_concat_list.txt -i temp/${chaptersFile} -map_metadata 1 -vf "split[bg][fg];[bg]scale=\${TARGET_W}:ih,boxblur=20:3[bg_b];[fg][bg_b]overlay=\${OX}:0" -c:v libx264 -preset ultrafast -c:a copy -pix_fmt yuv420p output/${basename}.mp4; fi`,
      `xattr -d com.apple.quarantine "$PWD/output/${basename}.mp4" 2>/dev/null; true`
    ];

    return ['export PATH=/opt/homebrew/bin:/usr/local/bin:$PATH', ...(simple ? simpleCmds : complexCmds)].join(' && ');
  })() }}

