assignments.value:
={{
(() => {
  const parsed = JSON.parse($json.text);
  const wordMap = parsed.wordMap;
  const target = $('Set Change-Voice Page Number').item.json.textToChange.trim().split(/\s+/).filter(w => w);
  const voice = $('Set Change-Voice Page Number').item.json.voice;

  let matchStart = -1;
  for (let i = 0; i <= wordMap.length - target.length; i++) {
    let ok = true;
    for (let k = 0; k < target.length; k++) {
      if (wordMap[i + k].original.toLowerCase() !== target[k].toLowerCase()) { ok = false; break; }
    }
    if (ok) { matchStart = i; break; }
  }
  if (matchStart === -1) return JSON.stringify({ found: false });

  const matchEnd = matchStart + target.length;
  const before = wordMap.slice(0, matchStart).map(w => w.normalized).join(' ');
  const middle = wordMap.slice(matchStart, matchEnd).map(w => w.normalized).join(' ');
  const after = wordMap.slice(matchEnd).map(w => w.normalized).join(' ');
  const wrapped = [before, `[voice:${voice}] ${middle} [voice:af_heart]`, after].filter(Boolean).join(' ');

  return JSON.stringify({ found: true, text: wrapped, wordMap: wordMap });
})()
}}
